  "hypothesis": "Replacing the coarse ray-step grid with an adaptively certified active-peak line search will recover transport improvements that lie below the old minimum step size or between its widely spaced trials.",
  "rationale": "The previous transport search produced essentially no gain, while its smallest tested step was still about 1.5e-5. Along each transport ray the numerator is quartic and every convolution peak is quadratic, so an active-peak model can search much smaller steps cheaply and check proposed optima against the full convolution.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'directions': (24, 4, 80),
    'support_threshold': (1e-12, 1e-16, 1e-7, 'log'),
    'max_transport': (1.0, 0.05, 1.0),
}


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + 0.70 * budget_s
    rng = np.random.default_rng(seed)
    original = init if init is not None else {'values': np.linspace(0.2, 1.0, 512).tolist()}
    raw = original.get('values', original.get('samples'))
    f = np.maximum(np.asarray(raw, dtype=np.float64), 0.0)
    n = len(f)
    if n < 3 or not np.max(f) > 0:
        return original

    def exact(x):
        cc = oaconvolve(x, x, mode='full')
        xx = np.linspace(-0.5, 0.5, len(cc) + 2)
        dx = np.diff(xx)
        yy = np.concatenate(([0.0], cc, [0.0]))
        a = float(np.sum((dx / 3.0) * (yy[:-1]**2 + yy[:-1]*yy[1:] + yy[1:]**2)))
        b = np.sum(np.abs(cc)) / (len(cc) + 1)
        return float(a / (b * np.max(np.abs(cc))))

    baseline = exact(f)
    f = f / np.max(f)
    m = 2*n - 1
    size = next_fast_len(m)

    def metric(cc):
        return float((2*np.sum(cc*cc) + np.sum(cc[:-1]*cc[1:])) /
                     (3*np.sum(np.abs(cc))*np.max(np.abs(cc))))

    if time.monotonic() >= deadline - 4:
        return original
    ff = rfft(f, size, workers=1)
    c = irfft(ff*ff, size, workers=1)[:m].copy()
    current = metric(c)
    best = None
    threshold = float(params['support_threshold'])

    def support(x):
        occupied = x > threshold
        changes = np.diff(np.concatenate(([False], occupied, [False])).astype(np.int8))
        starts = np.flatnonzero(changes == 1)
        ends = np.flatnonzero(changes == -1)
        lengths = ends-starts
        ix = np.flatnonzero(occupied)
        centers = np.repeat((starts+ends-1)*0.5, lengths)
        halves = np.repeat(np.maximum((lengths-1)*0.5, 1.0), lengths)
        return ix, np.clip((ix-centers)/halves, -1, 1), ix.astype(np.float64)/max(1, n-1)

    ix, local, position = support(f)
    transport_time = 0.7

    def ray_search(c, linear, quadratic, incumbent):
        # B(u,v) polarizes 2 sum(u^2) + sum(u[k]u[k+1]).
        def bilinear(u, v):
            return float(2*np.sum(u*v) + 0.5*np.sum(u[:-1]*v[1:] + v[:-1]*u[1:]))

        coeff = np.array([bilinear(c, c), 2*bilinear(c, linear),
                          bilinear(linear, linear) + 2*bilinear(c, quadratic),
                          2*bilinear(linear, quadratic), bilinear(quadratic, quadratic)])
        sums = np.array([np.sum(c), np.sum(linear), np.sum(quadratic)])
        upper = float(params['max_transport'])
        active = {int(np.argmax(c))}
        chosen, chosen_score = 0.0, incumbent
        # Exchange constraints until the reduced peak envelope agrees with
        # the full convolution at its proposed optimum.
        for exchange in range(10):
            if time.monotonic() >= deadline - 3:
                break
            ids = np.fromiter(sorted(active), dtype=np.int64)
            ac, al, aq = c[ids], linear[ids], quadratic[ids]

            def reduced(a):
                peak = float(np.max(ac + a*al + a*a*aq))
                numerator = float(np.polynomial.polynomial.polyval(a, coeff))
                total = float(np.polynomial.polynomial.polyval(a, sums))
                return numerator/(3*total*peak)

            grid = np.concatenate(([0.0], upper*np.geomspace(1e-13, 1.0, 33)))
            scores = np.empty(len(grid))
            for j, a in enumerate(grid):
                if time.monotonic() >= deadline - 3:
                    return chosen, chosen_score
                scores[j] = reduced(float(a))
            candidates = [(float(grid[j]), float(scores[j])) for j in np.argsort(scores)[-4:]]
            for j in np.argsort(scores)[-3:]:
                if time.monotonic() >= deadline - 3:
                    break
                lo, hi = grid[max(0, j-1)], grid[min(len(grid)-1, j+1)]
                if hi > lo:
                    result = minimize_scalar(lambda a: -reduced(a), bounds=(lo, hi),
                                             method='bounded', options={'xatol': 1e-15, 'maxiter': 70})
                    candidates.append((float(result.x), float(-result.fun)))
            a, predicted = max(candidates, key=lambda item: item[1])
            trial = c + a*linear + a*a*quadratic
            value = metric(trial)
            peak_index = int(np.argmax(trial))
            if value > chosen_score + 3e-15:
                chosen, chosen_score = a, value
            if peak_index in active or predicted <= chosen_score + 2e-14:
                break
            active.add(peak_index)
        return chosen, chosen_score

    for iteration in range(int(params['directions'])):
        if time.monotonic() >= deadline - max(4.0, 2.5*transport_time):
            break
        tick = time.monotonic()
        family = iteration % 12
        if family == 0:
            field = local.copy()
        elif family == 1:
            field = -local
        elif family == 2:
            field = np.ones(len(ix))
        elif family == 3:
            field = 2*position-1
        elif family == 4:
            field = -(2*position-1)
        elif family == 5:
            field = local*(2*position-1)
        elif family == 6:
            field = -local*(2*position-1)
        elif family == 7:
            field = np.sin(2*np.pi*position)
        elif family == 8:
            field = -np.sin(2*np.pi*position)
        elif family == 9:
            field = local*np.cos(2*np.pi*position)
        elif family == 10:
            field = -local*np.cos(2*np.pi*position)
        else:
            field = np.zeros(len(ix))
            for frequency in range(1, 5):
                if time.monotonic() >= deadline - 4:
                    break
                field += rng.normal()*np.sin(frequency*np.pi*position + rng.uniform(0, 2*np.pi))
            field /= max(1.0, float(np.max(np.abs(field))))
        if iteration >= 12:
            field *= -1
        target = np.clip(ix + np.where(field >= 0, 1, -1), 0, n-1)
        moved = f[ix]*np.minimum(np.abs(field), 1.0)
        delta = np.zeros(n)
        delta[ix] -= moved
        np.add.at(delta, target, moved)
        if time.monotonic() >= deadline - 4:
            break
        zz = rfft(delta, size, workers=1)
        linear = irfft(2*ff*zz, size, workers=1)[:m].copy()
        quadratic = irfft(zz*zz, size, workers=1)[:m].copy()
        chosen, chosen_score = ray_search(c, linear, quadratic, current)
        if chosen:
            f = np.maximum(f + chosen*delta, 0.0)
            ff = ff + chosen*zz
            c = c + chosen*linear + chosen*chosen*quadratic
            current = chosen_score
            best = f.copy()
            if time.monotonic() < deadline - 4:
                ix, local, position = support(f)
        transport_time = 0.5*transport_time + 0.5*(time.monotonic()-tick)
        del delta, linear, quadratic, zz

    if best is not None and time.monotonic() < start + 0.84*budget_s:
        if exact(best) > baseline:
            return {'samples': best.tolist()}
    return original
